// Prepare synthetic input only for the token-free, write-disabled native test.
import fs from 'node:fs/promises';import assert from 'node:assert/strict';import {nativeFixture,mapBundle} from '../outputs/ROMDex/tests/content-native-tree-fixture.mjs';import {sha} from '../outputs/ROMDex/content/contracts.mjs';
const info=JSON.parse(await fs.readFile('work/u20i/ui-window.json'));assert(info.isolated&&info.networkDisabled&&!info.credentialsCopied);const response=await fetch(info.origin+'/api/import/context');assert(response.ok);const context=await response.json(),f=nativeFixture(),bundle=JSON.parse(JSON.stringify(mapBundle(f)).replaceAll('fixture:new-','content:u20i-ui-new-'));bundle.workspaceId=context.workspaceId;bundle.expectedHead=context.expectedHead;bundle.records[0].parentRecordId=context.records.find(r=>r.kind==='region').recordId;bundle.records[0].current.payload.regionId=bundle.records[0].parentRecordId;bundle.records[0].current.payload.timelineRef=context.records.find(r=>r.kind==='shared').recordId;bundle.source={repositoryId:'content:u20i-ui-synthetic-source',revision:'Synthetic Native UI Verification; No ROM Extraction',artifactSha256:sha('U20I synthetic UI fixture'),verification:'documented'};bundle.reason='Isolated UI verification only; network writes are disabled.';for(const r of bundle.records)r.current.payload.name='U20I Synthetic '+r.current.payload.name;await fs.writeFile('work/u20i/ui-import.json',JSON.stringify(bundle,null,2)+'\n');console.log(JSON.stringify({prepared:true,records:bundle.records.length,isolated:true}));
